<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
use WexaShelf\{Growth,GrowthSite,Repository,ApiException,SEOSettings};
final class GrowthTestDB extends PDO{
 public function __construct(){parent::__construct('sqlite::memory:');$this->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$this->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$this->exec('CREATE TABLE ws_settings(setting_key TEXT PRIMARY KEY,value TEXT);CREATE TABLE ws_audit(id INTEGER PRIMARY KEY,action TEXT,subject TEXT,detail TEXT,createdAt TEXT);CREATE TABLE ws_records(kind TEXT,id TEXT,payload TEXT);');}
 public function prepare(string$query,array$options=[]):PDOStatement|false{$query=str_replace(['INSERT IGNORE',' FOR UPDATE','ON DUPLICATE KEY UPDATE value=VALUES(value)'],['INSERT OR IGNORE','','ON CONFLICT(setting_key) DO UPDATE SET value=excluded.value'],$query);return parent::prepare($query,$options);}
}
function growthCheck(bool$ok,string$label):void{if(!$ok)throw new RuntimeException($label);}
function growthReject(callable$fn,int$status=400):void{try{$fn();}catch(ApiException$e){growthCheck($e->status===$status,'Expected status '.$status);return;}throw new RuntimeException('Expected rejection');}
$db=new GrowthTestDB;$repo=new Repository($db);$config=['site'=>['url'=>'https://catalog.example.org/sub','indexing'=>true],'seo'=>SEOSettings::defaults(['site'=>['indexing'=>true]])];$growth=new Growth($db,$repo,$config);
$app=['id'=>'one','name'=>'One','description'=>'Source one','website'=>'https://example.org','platforms'=>['android'],'publisher'=>'Example'];$r=['id'=>'one','kind'=>'app','data'=>$app];$q=$db->prepare('INSERT INTO ws_records(kind,id,payload) VALUES(?,?,?)');$q->execute(['app','one',json_encode($r)]);
$draft=['id'=>'choose-notes','kind'=>'intent','locale'=>'en','slug'=>'choose-notes','revision'=>0,'status'=>'draft','seoApproved'=>false,'title'=>'Choose a note app','summary'=>'A source-backed choice guide.','topic'=>'notes','intent'=>'choose a note app','authorId'=>'','appIds'=>['one'],'sections'=>[['heading'=>'Requirements','paragraphs'=>['Check the documented export format before choosing.']]],'sources'=>[['title'=>'Official source','url'=>'https://example.org/docs','checkedAt'=>'2026-01-01']],'links'=>[],'seo'=>['title'=>'','description'=>'','noindex'=>false],'test'=>null,'reviewNote'=>''];
$saved=$growth->save($draft);growthCheck($saved['revision']===1,'Persistent draft revision');growthCheck($growth->publicDocuments(['apps'=>[$app]])===[],'Draft hidden');growthReject(fn()=>$growth->save($draft),409);
$published=$growth->save(array_replace($saved,['status'=>'published','seoApproved'=>true]));growthCheck(Growth::approved($published),'Unchanged reviewed publication approved');$docs=$growth->publicDocuments(['apps'=>[$app]]);growthCheck(count($docs)===1,'Published available');
$changed=$growth->save(array_replace($published,['title'=>'Updated note guide']));growthCheck(!$changed['seoApproved'],'Text edit clears approval');$approved=$growth->save(array_replace($changed,['seoApproved'=>true]));growthCheck(Growth::approved($approved),'Second explicit review');
$duplicate=$draft;$duplicate['id']='other-guide';growthReject(fn()=>$growth->save($duplicate),409);$duplicate['slug']='other-guide';$growth->save($duplicate);growthCheck(count($growth->insights()['warnings'])===1,'Duplicate intent warning');growthCheck(count($growth->insights()['orphans'])===1,'Published orphan');
$r['data']['description']='Changed source';$db->prepare('UPDATE ws_records SET payload=? WHERE id=?')->execute([json_encode($r),'one']);$docs=$growth->publicDocuments(['apps'=>[$app]]);growthCheck($docs[0]['stale']&&!Growth::approved($docs[0]),'App fingerprint invalidates current SEO');growthCheck($growth->publicDocuments(['apps'=>[]])===[],'Unavailable app prevents public page');
$restored=$growth->restore('choose-notes','en',1);growthCheck($restored['status']==='draft'&&!$restored['seoApproved']&&$restored['revision']===5,'Restore historical as new draft');
foreach([['title'=>'<script>bad</script>'],['unknown'=>'value'],['kind'=>'test','status'=>'published'],['kind'=>'comparison','status'=>'published']]as$patch)growthReject(fn()=>Growth::validate(array_replace($draft,$patch)));
growthReject(fn()=>Growth::validateLifecycle(['revision'=>0,'rules'=>[['from'=>'/en/old','to'=>'/en/new','status'=>301,'reason'=>'Moved'],['from'=>'/en/new','to'=>'/en/old','status'=>301,'reason'=>'Moved']]]));
growthReject(fn()=>Growth::validateLifecycle(['revision'=>0,'rules'=>[['from'=>'/api/admin','to'=>'/en/new','status'=>301,'reason'=>'Wrong']]]));
$rules=$growth->saveLifecycle(['revision'=>0,'rules'=>[['from'=>'/en/old','to'=>'/en/new','status'=>301,'reason'=>'Moved'],['from'=>'/en/removed','to'=>'','status'=>410,'reason'=>'Withdrawn']]]);growthCheck($growth->resolveLifecycle('/en/removed')['status']===410,'Gone rule persisted');growthReject(fn()=>$growth->saveLifecycle(['revision'=>0,'rules'=>[]]),409);
$csv="Query;Page;Clicks;Impressions;CTR;Position\nnotes;https://example.org/sub/page;1;100;1%;12,5\n";$import=Growth::parseGsc(['csv'=>$csv,'property'=>'https://example.org/sub','startDate'=>'2026-01-01','endDate'=>'2026-01-31']);growthCheck($import['rows'][0]['position']===12.5&&$import['rows'][0]['ctr']===0.01,'Locale CSV metrics');growthReject(fn()=>Growth::parseGsc(['csv'=>str_replace('example.org/sub/page','evil.example/page',$csv),'property'=>'https://example.org/sub','startDate'=>'2026-01-01','endDate'=>'2026-01-31']));$growth->importGsc(['csv'=>$csv,'property'=>'https://example.org/sub','startDate'=>'2026-01-01','endDate'=>'2026-01-31']);growthCheck(count($growth->state()['gsc']['imports'])===1,'CSV persisted without OAuth');
$backup=$growth->backup();$valid=Growth::validateBackup($backup);$repo->transaction(fn()=>$growth->restoreBackup($valid));growthCheck(count($growth->state()['documents'])===2&&count($growth->history('choose-notes','en'))===5,'Backup restore revisions');
$document=$approved;$document['stale']=false;$document['appIds']=[];ob_start();GrowthSite::render([$document],['apps'=>[],'records'=>[],'translations'=>[]],$config,Growth::path($document));$html=ob_get_clean();growthCheck(str_contains($html,'rel="canonical"')&&str_contains($html,'"serverOnly":true')&&!str_contains($html,'assets/app.js'),'Server-only canonical page');growthCheck(str_contains($html,'Requirements')&&str_contains($html,'Official source'),'Visible source-backed content');growthCheck(count(GrowthSite::sitemapEntries([$document],$config))===1,'Approved sitemap');$document['stale']=true;growthCheck(GrowthSite::sitemapEntries([$document],$config)===[],'Stale excluded sitemap');
echo "PASS growth: persistence/revisions/review/source-stale, intent/orphans, URL lifecycle loops, CSV boundary/locale parsing, backup restore, SSR and sitemap.\n";
